using System;
using System.Collections;
using System.Collections.Generic;
using LittleLeo;
using LittleLeo.Variables;
using NaughtyAttributes;
using UnityEngine;

namespace Astrea.BattleActions;

public class RandomLightningAction : LightningAction
{
	[Header("Action Specifics")]
	[SerializeField]
	private bool corrupt;

	[SerializeField]
	[ShowIf("corrupt")]
	private CorruptAction corruptAction;

	[SerializeField]
	[HideIf("corrupt")]
	private PurifyAction purifyAction;

	[SerializeField]
	private bool meteorRain;

	[SerializeField]
	[ShowIf("meteorRain")]
	private GameObjectReference playerGameObjectReference;

	[SerializeField]
	private bool ignoreElectrostaticField;

	[Header("Units")]
	[SerializeField]
	[HideIf("corrupt")]
	protected CurrentCorruptedAnimals currentCorruptedAnimals;

	[Header("VFX")]
	[SerializeField]
	private bool spawnVFXAndDelayBetweenPurifyCorruptEarly;

	[Header("SFX")]
	[SerializeField]
	private bool playSFXEvenWithoutVFXEnabled;

	[SerializeField]
	private bool enableDelayToSFX;

	[SerializeField]
	[ShowIf("enableDelayToSFX")]
	private float delayToSFX;

	public bool Corrupt => corrupt;

	public void CastVariableTimes(int timesAmount, List<GameObject> units, GameObject source, Action afterLightningAction = null, Action rightAfterLastLightningAction = null)
	{
		ActivateSafeCriticalOmen(source);
		ReferenceSingleton<GameStateManager>.Instance.ActionsQueueState.EnqueueAction(DefaultCast(timesAmount, base.CorruptPurifyAmountWithModifier, units, source, afterLightningAction, rightAfterLastLightningAction));
		ReferenceSingleton<GameStateManager>.Instance.SetActionsQueueState();
	}

	public void CastVariableTimesWithDelayToStart(int timesAmount, List<GameObject> units, GameObject source, float delayToStartCorruptedLightningAction, Action afterLightningAction = null, Action rightAfterLastLightningAction = null, Action beforeDelayAction = null)
	{
		ActivateSafeCriticalOmen(source);
		ReferenceSingleton<GameStateManager>.Instance.ActionsQueueState.EnqueueAction(DefaultCastWithDelayToStart(timesAmount, base.CorruptPurifyAmountWithModifier, units, source, delayToStartCorruptedLightningAction, afterLightningAction, rightAfterLastLightningAction, beforeDelayAction));
		ReferenceSingleton<GameStateManager>.Instance.SetActionsQueueState();
	}

	public void CastVariableAndTimesAmount(int timesAmount, int purifyCorruptAmount, List<GameObject> units, GameObject source, Action afterLightningAction = null, Action rightAfterLastLightningAction = null)
	{
		ActivateSafeCriticalOmen(source);
		ReferenceSingleton<GameStateManager>.Instance.ActionsQueueState.EnqueueAction(DefaultCast(timesAmount, purifyCorruptAmount, units, source, afterLightningAction, rightAfterLastLightningAction));
		ReferenceSingleton<GameStateManager>.Instance.SetActionsQueueState();
	}

	public void CastVariableAndTimesAmountWithActionAndDelayToStart(int timesAmount, int purifyCorruptAmount, List<GameObject> units, GameObject source, float delayToStartCorruptedLightningAction, Action afterLightningAction = null, Action rightAfterLastLightningAction = null, Action beforeDelayAction = null)
	{
		ActivateSafeCriticalOmen(source);
		ReferenceSingleton<GameStateManager>.Instance.ActionsQueueState.EnqueueAction(DefaultCastWithDelayToStart(timesAmount, purifyCorruptAmount, units, source, delayToStartCorruptedLightningAction, afterLightningAction, rightAfterLastLightningAction, beforeDelayAction));
		ReferenceSingleton<GameStateManager>.Instance.SetActionsQueueState();
	}

	protected IEnumerator DefaultCast(int timesAmount, int purifyCorruptAmount, List<GameObject> units, GameObject source, Action afterLightningAction = null, Action rightAfterLastLightningAction = null)
	{
		if (austra && meteorRain && ReferenceSingleton<BattleHandler>.Instance.IsSourcePlayerOrCompanions(source) && ReferenceSingleton<AustraOmensHandler>.Instance.PlayerHaveActivateMeteorShieldOmenAndActivateIt())
		{
			yield return new WaitForSeconds(1.5f);
		}
		yield return InvokeAlternatives.WaitOneFrame();
		CheckCancelAutoOnDiceCastedOnRuneCasted(source);
		bool isAnyTargetWithElectrostaticField = false;
		GameObject unitWithElectrostaticField = null;
		if (!ignoreElectrostaticField && ReferenceSingleton<BattleHandler>.Instance.IsSourcePlayerOrCompanions(source))
		{
			unitWithElectrostaticField = CheckTargetWithElectrostaticField(units, source);
			if ((bool)unitWithElectrostaticField)
			{
				isAnyTargetWithElectrostaticField = true;
			}
		}
		for (int i = 0; i < timesAmount; i++)
		{
			GameObject target = units.PickRandom();
			if (corrupt)
			{
				if (isAnyTargetWithElectrostaticField && (bool)unitWithElectrostaticField)
				{
					target = unitWithElectrostaticField;
				}
				if (meteorRain && ReferenceSingleton<BattleHandler>.Instance.IsSourcePlayerOrCompanions(source))
				{
					playerGameObjectReference.value.GetComponent<PlayerEffects>().IsPlayerSkyPiercerActivateIt();
				}
				if (spawnVFXAndDelayBetweenPurifyCorruptEarly && IsVFXEnabled())
				{
					if (meteorRain)
					{
						if (ReferenceSingleton<BattleHandler>.Instance.IsSourcePlayerOrCompanions(source))
						{
							SpawnVFX(GetVFXOwnerPosition(target), 3f);
						}
						else
						{
							SpawnSecondVFX(GetVFXOwnerPosition(target), 3f);
						}
					}
					else
					{
						SpawnVFX(GetVFXOwnerPosition(target), 3f);
					}
					if (enableDelayToSFX)
					{
						InvokeAlternatives.Invoke(ReferenceSingleton<CoroutineHandler>.Instance, delayToSFX, delegate
						{
							PlaySFX();
						});
					}
					else
					{
						PlaySFX();
					}
					if (i == timesAmount - 1)
					{
						rightAfterLastLightningAction?.Invoke();
					}
					yield return new WaitForSeconds(base.DelayBetweenCorruptPurify);
				}
				else if (playSFXEvenWithoutVFXEnabled)
				{
					PlaySFX();
				}
				corruptAction.CastTargetAmountXTime(target, purifyCorruptAmount, source);
			}
			else
			{
				if (isAnyTargetWithElectrostaticField)
				{
					if (i > 0)
					{
						unitWithElectrostaticField = CheckTargetWithElectrostaticField(units, source);
						if ((bool)unitWithElectrostaticField)
						{
							target = unitWithElectrostaticField;
						}
						else
						{
							isAnyTargetWithElectrostaticField = false;
						}
					}
					else
					{
						target = unitWithElectrostaticField;
					}
				}
				purifyAction.CastTargetAmountXTime(target, purifyCorruptAmount, source);
			}
			if (spawnVFXAndDelayBetweenPurifyCorruptEarly)
			{
				if (!IsVFXEnabled())
				{
					PlaySFX();
					SpawnVFX(GetVFXOwnerPosition(target), 3f);
					if (i == timesAmount - 1)
					{
						rightAfterLastLightningAction?.Invoke();
					}
					yield return new WaitForSeconds(base.DelayBetweenCorruptPurify);
				}
			}
			else
			{
				SpawnVFX(GetVFXOwnerPosition(target), 3f);
				if (IsVFXEnabled() || playSFXEvenWithoutVFXEnabled)
				{
					PlaySFX();
				}
				if (i == timesAmount - 1)
				{
					rightAfterLastLightningAction?.Invoke();
				}
				yield return new WaitForSeconds(base.DelayBetweenCorruptPurify);
			}
			if (!corrupt && currentCorruptedAnimals.activeCorruptedAnimals.Count == 0)
			{
				break;
			}
			if (IsTargetDefeated(target))
			{
				units.Remove(target);
				if (units.Count == 0)
				{
					break;
				}
			}
		}
		DeactivateSafeCriticalOmen();
		afterLightningAction?.Invoke();
		ReferenceSingleton<MiscOmensHandler>.Instance.ResetWickedsCardOmenAction?.Invoke(source);
	}

	protected IEnumerator DefaultCastWithDelayToStart(int timesAmount, int purifyCorruptAmount, List<GameObject> units, GameObject source, float delayToStartCorruptedLightningAction, Action afterLightningAction = null, Action rightAfterLastLightningAction = null, Action beforeDelayAction = null)
	{
		beforeDelayAction?.Invoke();
		yield return new WaitForSeconds(delayToStartCorruptedLightningAction);
		yield return ReferenceSingleton<CoroutineHandler>.Instance.Run(DefaultCast(timesAmount, purifyCorruptAmount, units, source, afterLightningAction, rightAfterLastLightningAction));
	}

	private bool IsTargetDefeated(GameObject target)
	{
		return target.GetComponent<CorruptionStats>().IsDefeated();
	}

	private GameObject CheckTargetWithElectrostaticField(List<GameObject> units, GameObject source)
	{
		for (int i = 0; i < units.Count; i++)
		{
			if (units[i].GetComponent<UnitEffects>().IsElectrostaticField())
			{
				return units[i];
			}
		}
		return null;
	}
}
